:root{
  --bg:#FFFFFF;
  --ink:#0A0A0A;
  --muted:#737373;
  --cream:#EDE8E0;
  --line:#E5E5E5;
  --safe-area-inset-top: env(safe-area-inset-top, 0px);
}

*{
  box-sizing:border-box
}

html{
  scroll-behavior:smooth
}

body{
  margin:0;
  background:var(--bg);
  color:var(--ink);
  font-family:Inter,"Helvetica Neue",Arial,system-ui,-apple-system,sans-serif;
  -webkit-font-smoothing:antialiased
}

a{
  color:inherit
}

button{
  font:inherit
}

.page{
  min-height:100vh;
  background:var(--bg);
  padding-top:var(--safe-area-inset-top)
}

/* NAV */

.nav-wrap{
  position:sticky;
  top:var(--safe-area-inset-top);
  z-index:30;
  background:rgba(255,255,255,.96);
  border-bottom:1px solid var(--line);
  backdrop-filter:blur(8px)
}

.nav{
  max-width:1180px;
  margin:0 auto;
  padding:14px 24px;
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:16px
}

.tabbar{
  position:sticky;
  top:calc(var(--safe-area-inset-top) + 64px);
  z-index:25;
  background:#fff;
  border-bottom:1px solid var(--line)
}

.tabbar-inner{
  max-width:1180px;
  margin:0 auto;
  padding:0 24px;
  display:flex;
  align-items:center;
  gap:4px;
  overflow-x:auto;
  scrollbar-width:none
}

.tabbar-inner::-webkit-scrollbar{
  display:none
}

.tab{
  border:0;
  background:transparent;
  padding:13px 12px 11px;
  font-size:14px;
  font-weight:600;
  color:#737373;
  border-bottom:2px solid transparent;
  cursor:pointer;
  white-space:nowrap
}

.tab:hover{
  color:#0A0A0A
}

.tab.active{
  color:#0A0A0A;
  border-bottom-color:#0A0A0A
}

.tab:focus-visible{
  outline:2px solid #0A0A0A;
  outline-offset:2px
}

.tab-note{
  margin-left:auto;
  font-size:11px;
  color:#A3A3A3;
  white-space:nowrap;
  padding-left:16px
}

.logo{
  display:flex;
  align-items:center;
  gap:10px;
  text-decoration:none
}

.logo-mark{
  width:34px;
  height:34px;
  border:1.8px solid #0A0A0A;
  border-radius:9px;
  display:grid;
  place-items:center;
  position:relative;
  background:#fff;
  flex:none
}

.logo-l{
  font-weight:900;
  font-size:19px;
  line-height:1;
  transform:translate(-2px,1px)
}

.logo-arrow{
  position:absolute;
  right:5px;
  top:3px;
  font-size:11px;
  font-weight:900
}

.logo-text{
  font-size:19px;
  letter-spacing:-.02em
}

.logo-text span{
  font-weight:900
}

.nav-center{
  display:flex;
  gap:28px
}

.nav-center a{
  text-decoration:none;
  font-size:14px;
  color:#262626
}

.nav-center a:hover{
  color:#000;
  text-decoration:underline;
  text-underline-offset:4px
}

.nav-right{
  display:flex;
  align-items:center;
  gap:18px
}

.login{
  text-decoration:none;
  font-size:14px;
  font-weight:600
}

.pill-black,.btn-black{
  background:#0A0A0A;
  color:#fff;
  border-radius:999px;
  padding:10px 18px;
  text-decoration:none;
  font-size:14px;
  font-weight:600;
  display:inline-flex;
  align-items:center;
  gap:6px;
  border:1px solid #0A0A0A;
  cursor:pointer
}

.pill-black:hover,.btn-black:hover{
  background:#222
}

.hamburger{
  display:none;
  background:#fff;
  border:1px solid var(--line);
  border-radius:8px;
  padding:8px;
  cursor:pointer
}

.mobile-menu{
  display:none;
  border-top:1px solid var(--line);
  padding:12px 24px 18px;
  flex-direction:column;
  gap:12px;
  background:#fff
}

.mobile-menu a{
  text-decoration:none;
  font-size:15px;
  font-weight:600
}

/* HERO */

.hero{
  max-width:1180px;
  margin:0 auto;
  padding:24px 24px 12px
}

.hero-grid{
  display:grid;
  grid-template-columns:1.05fr .95fr;
  gap:36px;
  align-items:center
}

.eyebrow{
  display:inline-flex;
  align-items:center;
  gap:8px;
  border:1px solid var(--line);
  border-radius:999px;
  padding:7px 12px;
  font-size:11px;
  letter-spacing:.14em;
  font-weight:700
}

.eyebrow-dot{
  width:7px;
  height:7px;
  border-radius:50%;
  background:#0A0A0A;
  display:inline-block
}

.hero h1{
  font-size:48px;
  line-height:1.02;
  letter-spacing:-.04em;
  margin:14px 0 12px;
  font-weight:800
}

.h1-underline{
  box-shadow:inset 0 -10px 0 #EDE8E0
}

.hero-sub{
  font-size:17px;
  line-height:1.55;
  color:#525252;
  max-width:480px;
  margin:0
}

.hero-actions{
  display:flex;
  gap:12px;
  margin:16px 0;
  flex-wrap:wrap
}

.btn-white{
  background:#fff;
  color:#0A0A0A;
  border:1px solid #0A0A0A;
  border-radius:999px;
  padding:12px 18px;
  font-weight:600;
  display:inline-flex;
  align-items:center;
  gap:8px;
  cursor:pointer
}

.btn-white:hover{
  background:#F5F5F5
}

.proof{
  display:flex;
  gap:12px;
  align-items:center
}

.avatars{
  display:flex
}

.avatars i{
  width:28px;
  height:28px;
  border-radius:50%;
  border:2px solid #fff;
  background:#D9D9D9;
  display:block;
  margin-left:-6px
}

.avatars i:first-child{
  margin-left:0
}

.avatars i:nth-child(2){
  background:#BFBFBF
}

.avatars i:nth-child(3){
  background:#A6A6A6
}

.avatars i:nth-child(4){
  background:#8A8A8A
}

.avatars b{
  width:28px;
  height:28px;
  border-radius:50%;
  background:#0A0A0A;
  color:#fff;
  display:grid;
  place-items:center;
  font-size:11px;
  margin-left:-6px;
  border:2px solid #fff
}

.stars{
  font-size:13px;
  letter-spacing:.08em
}

.stars span{
  color:#737373
}

.proof p{
  margin:2px 0 0;
  font-size:13px;
  color:#737373
}

.mock{
  border:1px solid var(--line);
  border-radius:18px;
  box-shadow:0 24px 60px rgba(0,0,0,.10);
  overflow:hidden;
  background:#fff
}

.mock-top{
  padding:20px 20px 14px;
  display:flex;
  justify-content:space-between;
  align-items:flex-start
}

.mock-kicker{
  font-size:10px;
  letter-spacing:.16em;
  color:#737373;
  font-weight:700
}

.mock-top h3{
  margin:6px 0 0;
  font-size:28px;
  letter-spacing:-.03em
}

.mock-top h3 em{
  font-style:normal;
  font-size:12px;
  background:#EDE8E0;
  padding:4px 8px;
  border-radius:999px;
  margin-left:8px;
  vertical-align:middle
}

.live{
  font-size:10px;
  letter-spacing:.14em;
  font-weight:800;
  border:1px solid var(--line);
  padding:6px 9px;
  border-radius:999px;
  display:flex;
  gap:6px;
  align-items:center
}

.live i{
  width:7px;
  height:7px;
  background:#16A34A;
  border-radius:50%;
  display:block
}

.mock-bars{
  padding:0 20px 16px;
  display:grid;
  gap:9px
}

.mock-bars div{
  display:grid;
  grid-template-columns:110px 1fr;
  align-items:center;
  gap:10px;
  font-size:12px;
  color:#737373
}

.mock-bars b{
  height:8px;
  background:#0A0A0A;
  border-radius:99px;
  display:block
}

.mock-leads{
  border-top:1px solid var(--line)
}

.lead-row{
  display:flex;
  align-items:center;
  gap:12px;
  padding:13px 20px;
  border-bottom:1px solid #F0F0F0
}

.lead-avatar{
  width:34px;
  height:34px;
  border-radius:50%;
  background:#EDE8E0;
  display:grid;
  place-items:center;
  font-size:11px;
  font-weight:800;
  flex:none
}

.lead-who{
  display:flex;
  flex-direction:column;
  flex:1;
  min-width:0
}

.lead-who b{
  font-size:13px
}

.lead-who small{
  font-size:11px;
  color:#737373;
  white-space:nowrap;
  overflow:hidden;
  text-overflow:ellipsis
}

.lead-score{
  display:flex;
  flex-direction:column;
  align-items:flex-end;
  gap:4px
}

.lead-score b{
  font-size:13px
}

.lead-score i{
  width:64px;
  height:5px;
  background:#0A0A0A;
  border-radius:99px;
  display:block
}

.mock-foot{
  padding:13px 20px;
  display:flex;
  justify-content:space-between;
  font-size:12px;
  color:#737373
}

/* STRIP */

.strip{
  border-top:1px solid var(--line);
  border-bottom:1px solid var(--line);
  padding:22px 24px;
  text-align:center
}

.strip p{
  font-size:11px;
  letter-spacing:.18em;
  color:#737373;
  margin:0 0 14px;
  font-weight:700
}

.strip-logos{
  display:flex;
  justify-content:center;
  gap:36px;
  flex-wrap:wrap;
  color:#A3A3A3;
  font-weight:900;
  letter-spacing:.08em;
  font-size:17px
}

/* SECTIONS */

.section{
  max-width:1180px;
  margin:0 auto;
  padding:72px 24px
}

.section-head{
  margin-bottom:32px
}

.kicker{
  font-size:11px;
  letter-spacing:.18em;
  color:#737373;
  font-weight:800
}

.section-head h2{
  font-size:40px;
  line-height:1.05;
  letter-spacing:-.03em;
  margin:12px 0 0
}

.cards{
  display:grid;
  grid-template-columns:repeat(3,1fr);
  gap:16px
}

.card{
  border:1px solid var(--line);
  border-radius:16px;
  padding:26px;
  background:#fff
}

.card-dark{
  background:#0A0A0A;
  color:#fff;
  border-color:#0A0A0A
}

.card-icon{
  width:44px;
  height:44px;
  border:1px solid var(--line);
  border-radius:12px;
  display:grid;
  place-items:center;
  margin-bottom:20px
}

.card-dark .card-icon{
  border-color:#333
}

.card h3{
  font-size:20px;
  margin:0 0 10px
}

.card p{
  font-size:14px;
  line-height:1.6;
  color:#737373;
  margin:0 0 22px
}

.card-dark p{
  color:#A3A3A3
}

.card a{
  display:inline-flex;
  align-items:center;
  gap:2px;
  text-decoration:none;
  font-weight:700;
  font-size:14px
}

.how{
  max-width:1180px;
  margin:0 auto;
  padding:18px 24px 72px
}

.steps{
  display:grid;
  grid-template-columns:repeat(3,1fr);
  gap:16px;
  border-top:1px solid #0A0A0A
}

.steps>div{
  padding-top:22px
}

.step-num{
  font-family:ui-monospace,monospace;
  font-size:12px;
  letter-spacing:.16em;
  color:#737373
}

.steps h3{
  font-size:22px;
  margin:12px 0 8px
}

.steps p{
  font-size:14px;
  line-height:1.6;
  color:#737373;
  margin:0
}

/* PANELS + SHOWCASE */

.panels{
  max-width:1180px;
  margin:0 auto;
  padding:28px 24px 20px
}

.panel-sub{
  color:#737373;
  line-height:1.6;
  max-width:620px;
  margin:12px 0 0;
  font-size:16px
}

.showcase{
  display:grid;
  grid-template-columns:repeat(3,1fr);
  gap:16px;
  margin-bottom:44px
}

.demo-frame{
  margin:0;
  border:1px solid var(--line);
  border-radius:16px;
  overflow:hidden;
  background:#fff;
  box-shadow:0 12px 30px rgba(0,0,0,.06);
  display:flex;
  flex-direction:column
}

.browser-chrome{
  display:flex;
  align-items:center;
  gap:5px;
  padding:10px 12px;
  border-bottom:1px solid var(--line);
  background:#FAFAFA
}

.browser-chrome i{
  width:9px;
  height:9px;
  border-radius:50%;
  background:#D9D9D9;
  display:block
}

.browser-chrome span{
  font-size:11px;
  color:#737373;
  margin-left:6px;
  flex:1;
  white-space:nowrap;
  overflow:hidden;
  text-overflow:ellipsis
}

.live-badge{
  font-size:9px;
  letter-spacing:.1em;
  background:#0A0A0A;
  color:#fff;
  padding:4px 7px;
  border-radius:999px
}

.demo-body{
  padding:18px;
  min-height:196px
}

.demo-head{
  display:flex;
  justify-content:space-between;
  font-size:12px;
  color:#525252
}

.pulse-dot{
  width:10px;
  height:10px;
  border-radius:50%;
  background:#16A34A;
  animation:pulse 1.4s infinite
}

@keyframes pulse{
  0%{
    box-shadow:0 0 0 0 rgba(22,163,74,.45)
  }

  100%{
    box-shadow:0 0 0 10px rgba(22,163,74,0)
  }
}

.score-big{
  font-size:58px;
  line-height:1;
  letter-spacing:-.05em;
  margin:12px 0 4px
}

.score-big small{
  font-size:18px;
  color:#A3A3A3
}

.score-label{
  font-size:10px;
  letter-spacing:.14em;
  font-weight:800;
  color:#16A34A
}

.anim-bars{
  margin-top:18px;
  display:grid;
  gap:9px
}

.anim-bars div{
  display:grid;
  grid-template-columns:78px 1fr;
  align-items:center;
  gap:8px;
  font-size:11px;
  color:#737373
}

.anim-bars b{
  height:8px;
  border-radius:99px;
  background:#0A0A0A;
  display:block;
  animation:grow 3s ease-in-out infinite
}

.bar-b{
  animation-delay:.3s
}

.bar-c{
  animation-delay:.6s
}

@keyframes grow{
  0%{
    width:12%
  }

  45%{
    width:92%
  }

  70%{
    width:68%
  }

  100%{
    width:12%
  }
}

.pipe-cols{
  display:flex;
  justify-content:space-between;
  font-size:10px;
  letter-spacing:.14em;
  font-weight:800;
  color:#737373
}

.pipe-track{
  display:flex;
  align-items:center;
  gap:8px;
  margin:22px 0 12px
}

.pipe-card{
  border:1px solid #0A0A0A;
  border-radius:10px;
  padding:10px 11px;
  font-size:12px;
  font-weight:700;
  animation:slideCard 3.6s ease-in-out infinite;
  background:#fff
}

.pipe-card.won{
  background:#0A0A0A;
  color:#fff
}

.pipe-arrow{
  font-weight:900
}

@keyframes slideCard{
  0%,20%{
    transform:translateX(0);
    opacity:1
  }

  55%{
    transform:translateX(58px)
  }

  80%,100%{
    transform:translateX(0)
  }
}

.pipe-progress{
  height:6px;
  background:#EDE8E0;
  border-radius:99px;
  overflow:hidden
}

.pipe-progress i{
  display:block;
  height:100%;
  width:50%;
  background:#0A0A0A;
  animation:slideBar 3.6s ease-in-out infinite
}

@keyframes slideBar{
  0%{
    transform:translateX(-100%)
  }

  55%{
    transform:translateX(120%)
  }

  100%{
    transform:translateX(-100%)
  }
}

.pipe-note{
  font-size:12px;
  color:#737373;
  margin:14px 0 0
}

.email-to{
  font-size:12px;
  color:#737373;
  border-bottom:1px solid #F0F0F0;
  padding-bottom:10px
}

.email-box{
  min-height:58px;
  font-size:14px;
  line-height:1.55;
  padding:14px 0
}

.typing-text{
  word-break:break-word
}

.caret{
  display:inline-block;
  width:2px;
  height:15px;
  background:#0A0A0A;
  margin-left:2px;
  vertical-align:-2px;
  animation:blink 1s steps(1) infinite
}

@keyframes blink{
  50%{
    opacity:0
  }
}

.email-foot{
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:8px;
  font-size:11px;
  color:#737373
}

.send-btn{
  border:0;
  background:#0A0A0A;
  color:#fff;
  border-radius:999px;
  padding:9px 13px;
  font-size:12px;
  font-weight:700;
  cursor:pointer;
  animation:pulseBtn 1.6s infinite;
  white-space:nowrap
}

@keyframes pulseBtn{
  0%,100%{
    transform:scale(1)
  }

  50%{
    transform:scale(1.05)
  }
}

.inline-ok{
  font-size:12px;
  color:#16A34A;
  margin:10px 0 0
}

.demo-frame figcaption{
  border-top:1px solid var(--line);
  padding:14px 16px;
  display:flex;
  flex-direction:column;
  gap:3px
}

.demo-frame figcaption b{
  font-size:14px
}

.demo-frame figcaption span{
  font-size:12px;
  color:#737373
}

.features-head{
  margin-top:8px
}

.docs-layout{
  display:grid;
  grid-template-columns:240px 1fr;
  gap:20px;
  align-items:start
}

.docs-side{
  border:1px solid var(--line);
  border-radius:16px;
  padding:16px;
  position:sticky;
  top:132px
}

.docs-search{
  display:flex;
  gap:8px;
  align-items:center;
  border:1px solid var(--line);
  border-radius:999px;
  padding:9px 12px
}

.docs-search input{
  border:0;
  outline:0;
  min-width:0;
  flex:1;
  font-size:14px
}

.side-label{
  font-size:10px;
  letter-spacing:.16em;
  color:#737373;
  font-weight:800;
  margin:18px 0 8px
}

.side-link{
  display:flex;
  align-items:center;
  gap:9px;
  width:100%;
  border:0;
  background:transparent;
  text-align:left;
  padding:10px 10px;
  border-radius:10px;
  cursor:pointer;
  font-size:14px;
  font-weight:600;
  color:#525252
}

.side-link.active{
  background:#0A0A0A;
  color:#fff
}

.side-note{
  display:flex;
  flex-direction:column;
  gap:3px;
  border-top:1px solid var(--line);
  margin-top:14px;
  padding-top:12px;
  font-size:12px;
  color:#737373
}

.docs-main h3{
  font-size:24px;
  margin:0
}

.docs-intro{
  color:#737373;
  line-height:1.6
}

.doc-block{
  border:1px solid var(--line);
  border-radius:14px;
  overflow:hidden;
  margin-bottom:14px
}

.doc-block-head{
  display:flex;
  justify-content:space-between;
  padding:13px 16px;
  background:#FAFAFA;
  border-bottom:1px solid var(--line)
}

.doc-block pre{
  margin:0;
  padding:16px;
  background:#0A0A0A;
  color:#EDE8E0;
  overflow:auto;
  font-size:13px;
  line-height:1.6;
  white-space:pre-wrap
}

.empty-docs{
  border:1px dashed var(--line);
  border-radius:12px;
  padding:20px;
  color:#737373
}

.billing-toggle{
  display:inline-flex;
  border:1px solid var(--line);
  border-radius:999px;
  padding:4px;
  background:#FAFAFA
}

.billing-toggle button{
  border:0;
  background:transparent;
  padding:9px 15px;
  border-radius:999px;
  cursor:pointer;
  font-weight:600
}

.billing-toggle button.on{
  background:#0A0A0A;
  color:#fff
}

.billing-note{
  color:#737373;
  font-size:14px
}

.price-grid{
  display:grid;
  grid-template-columns:repeat(3,1fr);
  gap:16px;
  margin-top:18px
}

.price-card{
  border:1px solid var(--line);
  border-radius:16px;
  padding:24px;
  position:relative
}

.price-card.dark{
  background:#0A0A0A;
  color:#fff
}

.price-card>span{
  font-size:11px;
  letter-spacing:.16em;
  font-weight:800
}

.price-card h3{
  font-size:40px;
  margin:12px 0 6px
}

.price-card h3 small{
  font-size:14px
}

.price-card p{
  color:#737373;
  margin:0 0 18px
}

.price-card.dark p{
  color:#A3A3A3
}

.price-card ul{
  list-style:none;
  padding:0;
  margin:0 0 22px;
  display:grid;
  gap:9px;
  font-size:14px
}

.price-card button{
  width:100%;
  border:1px solid #0A0A0A;
  background:#fff;
  border-radius:999px;
  padding:11px;
  cursor:pointer;
  font-weight:700
}

.price-card.dark button{
  background:#fff
}

.popular{
  position:absolute;
  right:16px;
  top:16px;
  background:#E9762B;
  color:#fff;
  border-radius:999px;
  padding:5px 8px;
  font-size:9px!important
}

.customer-quote{
  max-width:900px;
  margin:0 auto 28px
}

.customer-grid{
  display:grid;
  grid-template-columns:repeat(2,1fr);
  gap:16px
}

.customer-card{
  border:1px solid var(--line);
  border-radius:16px;
  padding:22px
}

.customer-card p{
  font-size:18px;
  line-height:1.5
}

.customer-card>div{
  display:flex;
  flex-direction:column
}

.customer-card>div span{
  font-size:13px;
  color:#737373
}

.timeline{
  max-width:760px;
  border-left:2px solid #0A0A0A;
  margin-left:8px
}

.timeline-row{
  position:relative;
  padding:0 0 30px 28px
}

.timeline-dot{
  position:absolute;
  left:-8px;
  top:5px;
  width:14px;
  height:14px;
  border-radius:50%;
  background:#fff;
  border:3px solid #0A0A0A
}

.version{
  font-family:ui-monospace,monospace;
  font-size:12px;
  color:#737373
}

.timeline-row h3{
  margin:6px 0
}

.timeline-row p{
  color:#737373;
  line-height:1.6;
  margin:0
}

.template-banner{
  display:flex;
  align-items:center;
  gap:10px;
  border:1px solid var(--line);
  border-radius:12px;
  padding:14px 16px;
  margin-bottom:18px;
  background:#FAFAFA
}

.template-grid{
  display:grid;
  grid-template-columns:repeat(3,1fr);
  gap:16px
}

.template-card{
  border:1px solid var(--line);
  border-radius:16px;
  padding:22px;
  display:flex;
  flex-direction:column;
  align-items:flex-start;
  gap:8px
}

.template-card.picked{
  border-color:#0A0A0A;
  box-shadow:0 0 0 1px #0A0A0A
}

.template-card h3{
  margin:0
}

.template-card p{
  color:#737373;
  margin:0;
  line-height:1.5
}

.template-card>span{
  font-size:12px;
  color:#737373
}

.template-card button{
  margin-top:auto;
  border:1px solid #0A0A0A;
  background:#fff;
  border-radius:999px;
  padding:9px 14px;
  cursor:pointer;
  font-weight:700
}

@media(max-width:820px){
  .showcase,.price-grid,.template-grid{
    grid-template-columns:1fr
  }

  .docs-layout{
    grid-template-columns:1fr
  }

  .docs-side{
    position:static
  }

  .customer-grid{
    grid-template-columns:1fr
  }

  .tab-note{
    display:none
  }

  .hero h1{
    font-size:32px
  }

  .hero-halftone .hwf-root{
    height:260px !important
  }

  .tabbar{
    top:calc(var(--safe-area-inset-top) + 64px)
  }
}

.metrics{
  max-width:1180px;
  margin:0 auto 72px;
  border-top:1px solid var(--line);
  border-bottom:1px solid var(--line);
  display:grid;
  grid-template-columns:repeat(4,1fr)
}

.metrics div{
  padding:30px 24px;
  text-align:center;
  border-right:1px solid var(--line)
}

.metrics div:last-child{
  border-right:0
}

.metrics b{
  display:block;
  font-size:38px;
  letter-spacing:-.04em
}

.metrics span{
  font-size:13px;
  color:#737373
}

.quote{
  max-width:900px;
  margin:0 auto;
  padding:0 24px 72px;
  text-align:center
}

.quote-mark{
  font-size:72px;
  line-height:.4;
  display:block;
  color:#E5E5E5
}

.quote blockquote{
  font-size:32px;
  line-height:1.25;
  letter-spacing:-.025em;
  font-weight:650;
  margin:22px 0
}

.quote-author{
  display:flex;
  align-items:center;
  justify-content:center;
  gap:12px
}

.quote-avatar{
  width:40px;
  height:40px;
  border-radius:50%;
  background:#0A0A0A;
  color:#fff;
  display:grid;
  place-items:center;
  font-size:12px;
  font-weight:800
}

.quote-author>div{
  display:flex;
  flex-direction:column;
  text-align:left
}

.quote-author>div span{
  font-size:13px;
  color:#737373
}

.quote-stars{
  font-size:12px;
  letter-spacing:.1em
}

/* CTA */

.cta-wrap{
  max-width:1180px;
  margin:0 auto;
  padding:0 24px 72px
}

.cta{
  background:#0A0A0A;
  color:#fff;
  border-radius:22px;
  padding:56px 32px;
  text-align:center
}

.cta h2{
  font-size:44px;
  line-height:1.02;
  letter-spacing:-.035em;
  margin:0
}

.cta p{
  color:#A3A3A3;
  margin:14px 0 26px
}

.cta form{
  display:flex;
  max-width:520px;
  margin:0 auto;
  gap:8px;
  background:#1A1A1A;
  border:1px solid #333;
  border-radius:999px;
  padding:6px
}

.cta input{
  flex:1;
  min-width:0;
  background:transparent;
  border:0;
  outline:0;
  color:#fff;
  padding:10px 14px;
  font-size:15px
}

.cta input::-moz-placeholder{
  color:#737373
}

.cta input::placeholder{
  color:#737373
}

.cta form button{
  background:#fff;
  color:#0A0A0A;
  border:0;
  border-radius:999px;
  padding:11px 18px;
  font-weight:700;
  display:flex;
  align-items:center;
  gap:6px;
  cursor:pointer;
  white-space:nowrap
}

.cta small{
  display:block;
  margin-top:16px;
  color:#737373;
  font-size:12px
}

.form-msg{
  margin:14px 0 0!important;
  font-size:14px!important
}

.form-msg.error{
  color:#FCA5A5!important
}

.form-msg.success{
  color:#BBF7D0!important;
  display:flex;
  align-items:center;
  justify-content:center;
  gap:6px
}

/* FOOTER HINT + WRAPPER */

.footer-hint{
  background:#0A0A0A;
  color:#737373;
  padding:18px 24px 0;
  text-align:center;
  font-family:ui-monospace,SFMono-Regular,Menlo,monospace;
  font-size:11px;
  letter-spacing:.14em;
  text-transform:uppercase
}

.footer-hint b{
  color:#EDE8E0;
  font-weight:500
}

.hwf-wrap{
  width:100%
}

.hwf-wrap .hwf-root{
  height:560px
}

