  color:#737373;
  padding:18px 24px 0;
  text-align:center;
  font-family:ui-monospace,SFMono-Regular,Menlo,monospace;
  font-size:11px;
  letter-spacing:.14em;
  text-transform:uppercase;
  margin:0;
  border:0
