.hero-halftone-hint b{
  color:#0A0A0A;
  font-weight:500
}

@media(max-width:820px){
  .nav-center,.nav-right{
    display:none
  }

  .hamburger{
    display:block
  }

  .mobile-menu{
    display:flex
  }

  .hero{
    padding-top:24px
  }

  .hero-grid{
    grid-template-columns:1fr;
    gap:24px
  }

  .hero h1{
    font-size:32px
  }

  .cards,.steps{
    grid-template-columns:1fr
  }

  .metrics{
    grid-template-columns:1fr 1fr
  }

  .metrics div:nth-child(2){
    border-right:0
  }

  .metrics div{
    border-bottom:1px solid var(--line)
  }

  .section-head h2{
    font-size:32px
  }

  .quote blockquote{
    font-size:24px
  }

  .cta{
    padding:40px 20px
  }

  .cta h2{
    font-size:34px
  }

  .cta form{
    flex-direction:column;
    background:transparent;
    border:0;
    padding:0
  }

  .cta input{
    background:#1A1A1A;
    border:1px solid #333;
    border-radius:999px
  }

  .cta form button{
    justify-content:center
  }

  .hwf-wrap .hwf-root{
    height:520px
  }

  .hero-halftone{
    margin:0;
    padding:0 0 28px;
    border:0;
    border-radius:0;
    box-shadow:none;
    overflow:visible
  }

  .hero-halftone .hwf-root{
    height:360px !important;
    overflow:visible
  }
}

@media(max-width:430px){
  .nav{
    padding-left:16px;
    padding-right:16px
  }

  .hero,.section,.how,.cta-wrap{
    padding-left:16px;
    padding-right:16px
  }

  .strip-logos{
    gap:20px
  }

  .mock-foot{
    flex-direction:column;
    gap:4px
  }

  .lead-who small{
    white-space:normal
  }
}

@media(prefers-color-scheme:dark){
  :root{
    --bg:#FFFFFF;
    --ink:#0A0A0A
  }
}

