x;align-items:center;gap:7px;color:#858585;font-size:12px;margin-top:23px}.hero-footer{font-size:12px;color:#777}.right{display:flex;flex-direction:column;min-width:0}.top{height:68px;padding:20px 48px;display:flex;align-items:center}.main-content{flex:1;display:flex;flex-direction:column;justify-content:center;align-items:center;padding:40px 24px 75px}.card{width:100%;max-width:400px;border:1px solid #e7e7e7;border-radius:16px;background:white;padding:32px 28px;box-shadow:0 15px 48px rgba(0,0,0,.07);animation:enter .4s ease both}h2{font-size:24px;line-height:1.25;letter-spacing:-.03em;margin:0;font-weight:750}.sub{font-size:14px;line-height:1.5;color:#6d6d6d;margin:8px 0 27px}.field{margin:0 0 20px}label{display:block;font-size:13px;font-weight:550;margin-bottom:8px}input{width:100%;height:44px;border:1px solid #dedede;border-radius:12px;padding:0 14px;font:inherit;font-size:14px;outline:none;background:white;color:#171717;transition:border-color .15s,box-shadow .15s}input::placeholder{color:#999}input:focus{border-color:#606060;box-shadow:0 0 0 3px #00000012}.password-wrap{position:relative}.password-wrap input{padding-right:68px}.password-wrap button{position:absolute;right:8px;top:0;height:44px;background:none;border:0;color:#666;cursor:pointer;font-size:12px;padding:0 8px}.challenge{min-height:0;margin:0 0 12px}.challenge:empty{margin:0}.primary{border:0;border-radius:999px;min-height:44px;width:100%;background:#050505;color:#fff;font:inherit;font-size:14px;font-weight:650;cursor:pointer;transition:transform .15s,background .15s}.primary:not(:disabled):hover{background:#303030}.primary:not(:disabled):active{transform:scale(.985)}.primary:disabled{background:#8c8c8c;cursor:not-allowed}.error{font-size:13px;line-height:1.5;color:#9d2222;background:#fff4f4;border:1px solid #f2d5d5;border-radius:10px;padding:10px 12px;margin:0 0 14px}.back{margin-top:20px;padding:8px 0;border:0;background:none;color:#555;font-size:13px;cursor:pointer}.card-footer{width:100%;max-width:400px;display:flex;justify-content:space-between;gap:12px;color:#7d7d7d;font-size:12px;margin-top:18px}.card-footer span:last-child{color:#333}button:focus-visible{outline:3px solid #929292;outline-offset:3px}[hidden]{display:none!important}@keyframes enter{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:translateY(0)}}@media(max-width:900px){.layout{grid-template-columns:1fr}.hero{min-height:auto}.hero-content{min-height:auto;padding:24px}.hero-top .pill,.hero-footer{display:none}.hero-center{padding:40px 0 48px}.hero-center h1{font-size:34px}.feature-card{display:none}.top{display:none}.main-content{padding:36px 20px 60px}.card{max-width:440px}.card-footer{max-width:440px}}@media(max-width:420px){.hero-center{padding:32px 0 36px}h1{font-size:32px}.card{padding:28px 22px}.card-footer{font-size:11px}.pill{display:none}}@media(prefers-reduced-motion:reduce){*,*::before,*::after{animation:none!important;transition:none!important}.hero-art{background-image:none!important}}

