t:44px;display:grid;place-items:center;border:1px solid #ddd;border-radius:10px;font-size:21px;margin-bottom:16px}.empty h3{font-size:16px;margin:0 0 8px}.empty p{max-width:390px;color:#666;font-size:14px;line-height:1.55;margin:0 0 16px}.text-link{font-size:13px;font-weight:700;text-decoration:none}.text-link:hover{text-decoration:underline}.footnote{font-size:12px;color:#777;margin:28px 0}.menu[aria-expanded="true"]{background:#f5f5f5}@media(max-width:760px){.workspace{display:block}.sidebar{display:none;position:fixed;z-index:10;top:70px;left:0;bottom:0;width:min(300px,85vw);height:calc(100dvh - 70px);box-shadow:0 8px 24px #0002}.sidebar.open{display:flex}.topbar{height:70px;padding:0 16px}.menu{display:grid;place-items:center}.crumb{gap:8px}.top-docs{font-size:12px}main{padding:36px 20px 64px}.heading{align-items:flex-start;flex-direction:column;gap:20px}.heading h1{font-size:28px}.panel-header{padding:20px}.empty{min-height:280px;padding:32px 20px}}@media(prefers-reduced-motion:no-preference){.nav a,.outline{transition:background .15s ease}}

