(()=>{const $=id=>document.getElementById(id),links=[...document.querySelectorAll('[data-section]')];let folder='inbox',rows=[],selected=null;
const safe=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const sections={overview:['Overview','A concise view of your email operations.'],emails:['Emails','Incoming messages, sending history and suppression records.'],logs:['Logs','Review outbound submission and processing records.'],broadcasts:['Broadcasts','Campaign sending is not enabled.'],audiences:['Audiences','Contact management and consent records.'],templates:['Templates','Reusable email content and local HTML preview.'],domains:['Domains','Verified sending identities.'],webhooks:['Webhooks','Account-scoped event delivery.'],settings:['Settings','Identity, access and mail configuration.']};
async function api(path,options={}){const r=await fetch(path,{credentials:'same-origin',cache:'no-store',...options,headers:{'content-type':'application/json',...(options.headers||{})}});const d=await r.json().catch(()=>({}));if(!r.ok)throw Error(d.error||'Request failed');return d;}
function inject(){const panel=$('workspace-panel');panel.innerHTML='<div class="panel-header"><div><h2 id="mail-title">Workspace overview</h2><p id="mail-subtitle">Account and email operations.</p></div><a class="text-link" id="mail-docs" href="/docs.html">Documentation ↗</a></div><div id="overview-content"><div class="lm-stats"><div><span>Inbox</span><strong id="lm-inbox">—</strong></div><div><span>Sent</span><strong id="lm-sent">—</strong></div><div><span>Unsuccessful</span><strong id="lm-failed">—</strong></div><div><span>Unsubscribed</span><strong id="lm-unsub">—</strong></div></div><div class="lm-account"><div><small>Account ID</small><code id="workspace-account-id">Loading…</code></div><div><small>API base URL</small><code id="workspace-api-url">Loading…</code></div><div><small>Dedicated inbound mailbox</small><code>inbound@inbound.leadmaster.jelvan.pro</code></div></div></div><div id="email-content" hidden><div class="lm-email-head"><div class="lm-tabs" role="tablist" aria-label="Email folders">'+[['inbox','Inbox'],['sent','Sent'],['bounced','Bounced'],['unsuccessful','Unsuccessful'],['unsubscribed','Unsubscribed']].map(([k,v])=>'<button type="button" data-folder="'+k+'" aria-selected="'+(k==='inbox')+'">'+v+' <span id="count-'+k+'">0</span></button>').join('')+'</div><button type="button" class="primary" id="lm-compose">Compose</button></div><div class="lm-filters"><input id="lm-search" type="search" placeholder="Search messages"><select id="lm-domain"><option value="">All domains</option><option>jelvan.pro</option><option>operavaglobal.com</option></select><button type="button" class="outline" id="lm-refresh">Refresh</button></div><p class="lm-note" id="lm-note"></p><div class="lm-table-wrap"><table class="lm-table"><thead><tr><th>Sender / recipient</th><th>Subject</th><th>Date</th><th>Status</th></tr></thead><tbody id="lm-rows"><tr><td colspan="4">Loading…</td></tr></tbody></table></div><div id="lm-detail" hidden><div class="lm-actions"><button class="outline" id="lm-back">← Back</button><button class="outline" id="lm-read">Mark unread</button><button class="outline" id="lm-archive">Archive</button><a id="lm-source" class="outline" hidden>Download original .eml</a></div><h3 id="lm-subject"></h3><dl id="lm-meta"></dl><pre id="lm-body"></pre><p id="lm-attachments"></p></div></div><div id="other-content" hidden class="lm-other"></div>';
const dialog=document.createElement('dialog');dialog.id='lm-dialog';dialog.innerHTML='<form id="lm-form"><div class="lm-dialog-head"><div><h2>Compose email</h2><p>Send through AWS SES SMTP.</p></div><button type="button" id="lm-close" aria-label="Close">×</button></div><label>To<input name="to" type="email" required maxlength="254"></label><label>From<select name="fromEmail" id="lm-from"><option value="hello@work.jelvan.pro">Jelvan Ricolcol &lt;hello@work.jelvan.pro&gt;</option><option value="hello@operavaglobal.com">Operava &lt;hello@operavaglobal.com&gt;</option><option value="custom">Other verified domain address…</option></select></label><label id="lm-custom-wrap" hidden>Other sender<input name="customFrom" type="email" placeholder="name@jelvan.pro"></label><label>Subject<input name="subject" required maxlength="300"></label><label>Message<textarea name="text" rows="7" required maxlength="200000"></textarea></label><p>Replies are sent to your registered superadmin email. SES acceptance is not proof of delivery.</p><p id="lm-error" role="alert" hidden></p><div class="lm-actions"><button type="button" class="outline" id="lm-cancel">Cancel</button><button type="submit" class="primary" id="lm-send">Send email</button></div></form>';document.body.append(dialog);}
function updateCounts(c){for(const k of ['inbox','sent','bounced','unsuccessful','unsubscribed']){const n=$('count-'+k);if(n)n.textContent=c[k]??0;}if($('lm-inbox'))$('lm-inbox').textContent=c.inbox??0;if($('lm-sent'))$('lm-sent').textContent=c.sent??0;if($('lm-failed'))$('lm-failed').textContent=c.unsuccessful??0;if($('lm-unsub'))$('lm-unsub').textContent=c.unsubscribed??0;}
async function loadCounts(){try{const d=await api('/api/admin/mail?folder=counts');updateCounts(d.counts||{});if($('workspace-account-id'))$('workspace-account-id').textContent=window.__lmAccount?.id||'Unavailable';if($('workspace-api-url'))$('workspace-api-url').textContent=window.__lmAccount?.api_base_url||'Unavailable';}catch{}}
function renderRows(){const b=$('lm-rows');if(!rows.length){b.innerHTML='<tr><td colspan="4" class="lm-empty">No '+safe(folder)+' records.</td></tr>';return;}b.innerHTML=rows.map(r=>'<tr data-id="'+safe(r.id)+'"><td><strong>'+safe(folder==='sent'?r.recipient:r.from_address||r.email||'')+'</strong></td><td>'+safe(r.subject||'(no subject)')+'</td><td>'+safe(new Date(r.received_at||r.created_at||0).toLocaleString())+'</td><td><span class="status">'+safe(r.status||r.delivery_status||'Received')+'</span></td></tr>').join('');b.querySelectorAll('[data-id]').forEach(x=>x.addEventListener('click',()=>openMessage(x.dataset.id)));}
async function loadFolder(){if(selected)return;$('lm-rows').innerHTML='<tr><td colspan="4" class="lm-empty">Loading…</td></tr>';try{const q=new URLSearchParams({folder,q:$('lm-search').value.trim(),domain:$('lm-domain').value});const d=await api('/api/admin/mail?'+q);rows=d.items||[];updateCounts(d.counts||{});$('lm-note').textContent=d.note||'';renderRows();}catch(e){$('lm-rows').innerHTML='<tr><td colspan="4" class="lm-empty">'+safe(e.message)+'</td></tr>';}}
async function openMessage(id){try{selected=await api('/api/admin/mail/'+encodeURIComponent(id));$('lm-detail').hidden=false;document.querySelector('.lm-email-head').hidden=true;document.querySelector('.lm-filters').hidden=true;document.querySelector('.lm-table-wrap').hidden=true;$('lm-subject').textContent=selected.subject||'(no subject)';$('lm-meta').innerHTML='<dt>From</dt><dd>'+safe(selected.from_address||selected.sender||'')+'</dd><dt>To</dt><dd>'+safe(selected.to_address||selected.recipient||'')+'</dd><dt>Date</dt><dd>'+safe(new Date(selected.received_at||selected.created_at||0).toLocaleString())+'</dd>';$('lm-body').textContent=selected.text_body||'No text body was extracted. Download the original message for full MIME content.';$('lm-read').textContent=selected.read_at?'Mark unread':'Mark read';$('lm-archive').hidden=folder!=='inbox';$('lm-source').hidden=!selected.download_url;$('lm-source').href=selected.download_url||'#';$('lm-attachments').textContent=selected.attachments?.length?selected.attachments.length+' attachment(s) are present in the original message.':'No attachments detected.';}catch(e){$('lm-note').textContent=e.message;}}
function back(){selected=null;$('lm-detail').hidden=true;document.querySelector('.lm-email-head').hidden=false;document.querySelector('.lm-filters').hidden=false;document.querySelector('.lm-table-wrap').hidden=false;loadFolder();}
async function patch(p){if(!selected)return;await api('/api/admin/mail/'+selected.id,{method:'PATCH',body:JSON.stringify(p)});back();loadCounts();}
function render(){const k=location.hash.slice(1),id=Object.hasOwn(sections,k)?k:'overview';const [title,desc]=sections[id];$('section-title').textContent=title;$('breadcrumb').textContent=title;$('section-description').textContent=desc;links.forEach(a=>a.dataset.section===id?a.setAttribute('aria-current','page'):a.removeAttribute('aria-current'));$('overview-content').hidden=id!=='overview';$('email-content').hidden=id!=='emails';$('other-content').hidden=['overview','emails'].includes(id);$('mail-title').textContent=id==='overview'?'Workspace overview':title;$('mail-subtitle').textContent=desc;$('mail-docs').href=id==='emails'?'/docs.html#email':id==='webhooks'||id==='logs'?'/developer-api-keys.html':'/docs.html';$('other-content').innerHTML=id==='broadcasts'||id==='audiences'||id==='templates'?'<p>This module is not fully enabled in production. No live functionality is represented here.</p>':id==='webhooks'?'<p>Manage account-scoped webhooks in the <a href="/developer-api-keys.html">API console</a>.</p>':id==='settings'?'<p>Authentication is protected by password, email OTP, Turnstile and secure session cookies. <a href="/privacy.html">Privacy policy</a>.</p>':id==='domains'?'<p>Verified sending identities: <code>jelvan.pro</code>, <code>leadmaster.jelvan.pro</code> and <code>operavaglobal.com</code>. Manage DNS and SES identities in their respective consoles.</p>':'<p>Review sent, failed and uncertain submissions in the Emails section.</p>';document.title=title+' · LeadMASTER';if(id==='emails')loadFolder();if(id==='overview')loadCounts();}
inject();const menu=$('menu');menu?.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';$('sidebar').classList.toggle('open',open);menu.setAttribute('aria-expanded',String(open));});links.forEach(a=>a.addEventListener('click',()=>{if(menu){$('sidebar').classList.remove('open');menu.setAttribute('aria-expanded','false');}}));window.addEventListener('hashchange',render);
document.addEventListener('click',e=>{const b=e.target.closest('[data-folder]');if(!b)return;folder=b.dataset.folder;document.querySelectorAll('[data-folder]').forEach(x=>x.setAttribute('aria-selected',String(x===b)));back();});$('lm-refresh').addEventListener('click',()=>{loadFolder();loadCounts();});$('lm-search').addEventListener('input',loadFolder);$('lm-domain').addEventListener('change',loadFolder);$('lm-back').addEventListener('click',back);$('lm-read').addEventListener('click',()=>patch({read:!selected.read_at}));$('lm-archive').addEventListener('click',()=>patch({archive:true}));
const dlg=$('lm-dialog');$('lm-compose').addEventListener('click',()=>dlg.showModal());$('lm-close').addEventListener('click',()=>dlg.close());$('lm-cancel').addEventListener('click',()=>dlg.close());$('lm-from').addEventListener('change',()=>$('lm-custom-wrap').hidden=$('lm-from').value!=='custom');
$('lm-form').addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget),from=$('lm-from').value==='custom'?f.get('customFrom'):$('lm-from').value;const btn=$('lm-send');btn.disabled=true;try{await api('/api/admin/send',{method:'POST',body:JSON.stringify({to:f.get('to'),fromEmail:from,subject:f.get('subject'),text:f.get('text')})});dlg.close();folder='sent';document.querySelector('[data-folder="sent"]').click();loadCounts();}catch(err){$('lm-error').textContent=err.message;$('lm-error').hidden=false;}finally{btn.disabled=false;}});
$('logout-link')?.addEventListener('click',async e=>{e.preventDefault();try{await api('/api/auth/logout',{method:'POST',body:'{}'});}finally{location.replace('/login.html');}});
async function verify(){try{const d=await api('/api/auth/session');if(!d.authenticated)throw Error();window.__lmAccount=d.account;$('workspace-name').textContent=d.account?.name||'LeadMASTER';$('workspace-email').textContent=d.email||'';$('workspace-status-description').textContent='Authenticated account connected. Dedicated inbound mail is stored separately from your existing email routes.';await loadCounts();render();}catch{location.replace('/login.html');}}
verify();
})();

/html-preview.js.body:
'use strict';
(() => {
  const el=id=>document.getElementById(id);
  const section=el('html-preview'), input=el('preview-html'), frame=el('preview-frame');
  const feedback=el('preview-feedback'),empty=el('preview-empty'),canvas=el('preview-canvas');
  const state={emails:'',templates:''};let current=null;
  const policy="default-src 'none'; img-src data:; style-src 'unsafe-inline'; font-src data:; object-src 'none'; frame-src 'none'; form-action 'none'; base-uri 'none'";
  function message(text,error=false){feedback.textContent=text;feedback.classList.toggle('is-error',error)}
  function resetFrame(){frame.hidden=true;frame.removeAttribute('srcdoc');empty.hidden=false}
  function changeSection(){
    const key=location.hash.slice(1);
    const next=Object.hasOwn(state,key)?key:null;
    if(next===current)return;
    current=next;section.hidden=!next;el('workspace-panel').hidden=Boolean(next);resetFrame();message('');
    if(next){input.value=state[next];el('html-preview-title').textContent=next==='emails'?'Compose email · HTML preview':'Template · HTML preview';el('html-preview-description').textContent=next==='emails'?'Preview message HTML before sending.':'Preview reusable template HTML.';}
  }
  input.addEventListener('input',()=>{if(current)state[current]=input.value;if(!frame.hidden){resetFrame();message('Content changed. Select Preview HTML to refresh.')}});
  el('preview-clear').addEventListener('click',()=>{input.value='';if(current)state[current]='';resetFrame();message('Preview cleared.');input.focus()});
  el('preview-render').addEventListener('click',()=>{
    resetFrame();
    if(!input.value.trim()){message('Enter HTML to preview.',true);input.focus();return}
    if(!window.DOMPurify?.isSupported){message('HTML preview is unavailable. Please reload the page.',true);return}
    try {
      // Sanitize before placing the document in an isolated sandbox.
      // External loads and active links are blocked by the CSP, sanitizer and iframe sandbox.
      const clean=window.DOMPurify.sanitize(input.value,{WHOLE_DOCUMENT:true,FORBID_TAGS:['script','iframe','frame','frameset','object','embed','base','link','meta','form','svg','math'],FORBID_ATTR:['srcset','action','formaction','href','xlink:href']});
      frame.srcdoc='<!doctype html><meta http-equiv="Content-Security-Policy" content="'+policy+'">'+clean;
      empty.hidden=true;frame.hidden=false;message('Preview updated.');
    } catch {resetFrame();message('Unable to render this HTML. Please try again.',true)}
  });
  for(const mode of ['desktop','mobile'])el('preview-'+mode).addEventListener('click',()=>{canvas.classList.toggle('is-mobile',mode==='mobile');el('preview-desktop').setAttribute('aria-pressed',String(mode==='desktop'));el('preview-mobile').setAttribute('aria-pressed',String(mode==='mobile'));});
  window.addEventListener('hashchange',changeSection);changeSection();
})();
